PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rooms(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,public_enabled INTEGER NOT NULL DEFAULT 0,internal_enabled INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tables(id INTEGER PRIMARY KEY AUTOINCREMENT,room_id INTEGER NOT NULL REFERENCES rooms(id),code TEXT NOT NULL,shape TEXT NOT NULL DEFAULT 'square',seats INTEGER NOT NULL DEFAULT 4,x REAL NOT NULL DEFAULT 70,y REAL NOT NULL DEFAULT 70,w REAL NOT NULL DEFAULT 70,h REAL NOT NULL DEFAULT 60,rotation REAL NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,group_code TEXT NOT NULL DEFAULT '',UNIQUE(room_id,code));
CREATE TABLE IF NOT EXISTS reservations(id INTEGER PRIMARY KEY AUTOINCREMENT,book_date TEXT NOT NULL,service TEXT NOT NULL,time TEXT NOT NULL,party_size INTEGER NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'web',room_id INTEGER REFERENCES rooms(id),status TEXT NOT NULL DEFAULT 'confirmed',cancel_token_hash TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reservation_tables(reservation_id INTEGER NOT NULL REFERENCES reservations(id) ON DELETE CASCADE,table_id INTEGER NOT NULL REFERENCES tables(id),book_date TEXT NOT NULL,service TEXT NOT NULL,PRIMARY KEY(reservation_id,table_id),UNIQUE(table_id,book_date,service));
CREATE TABLE IF NOT EXISTS menu_items(id INTEGER PRIMARY KEY AUTOINCREMENT,section TEXT NOT NULL DEFAULT 'piatti',category TEXT NOT NULL DEFAULT 'Specialità',name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price TEXT NOT NULL DEFAULT '',allergens TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL DEFAULT '',region TEXT NOT NULL DEFAULT '',winery TEXT NOT NULL DEFAULT '',vintage TEXT NOT NULL DEFAULT '',available INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS gallery(id INTEGER PRIMARY KEY AUTOINCREMENT,image_url TEXT NOT NULL,caption TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT 'Ambienti',sort_order INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_booking ON reservations(book_date,service,status);
